scripts.preRequest:
// Session variables live in memory only - never written to disk.
frap.vars.set('CODE', frap.vars.get('CODE') === '404' ? '200' : '404')
frap.console.log('asking for', frap.vars.get('CODE'))

scripts.postResponse:
frap.test('got the status we asked for', () => {
  frap.expect(String(frap.response.status)).toBe(frap.vars.get('CODE'))
})
